import six

from ute_common_abstract_core import logger
from ..utils import param_checker


class DataTransferDefinition:
    """Object for encapsulating data transfer parameters."""
    DEFAULT_DURATION = 9999 * 24 * 60 * 60  # 9999 days
    DEFAULT_TPUT = 100
    DEFAULT_BEARER = 'UeAutomatic'
    DEFAULT_PROTOCOL = 'udp'

    def __init__(self, direction, duration='forever', throughput='100Kbits/sec', bearer="UeAutomatic", protocol='udp',
                 protocol_details=None, **kwargs):
        """
        Basic initialization.

        :param direction: 'ul', 'dl' or 'simultaneous_ul_dl'
        :param duration: Data transfer duration in Robot time string format. e.g.  '1 minutes 42 seconds' or '1min 42s'.
            Default value is 'forever'; you need to call stop_data_transfer()
        :param throughput: desired data transfer throughput in string format. e.g. '1 MBytes/sec'; units:
            - 'bits/sec'
            - 'Kbits/sec'           1 000 bits/sec
            - 'Mbits/sec'       1 000 000 bits/sec
            - 'Gbits/sec'   1 000 000 000 bits/sec
            - 'Bytes/sec'               8 bits/sec
            - 'KBytes/sec'          1 000 Bytes/sec
            - 'MBytes/sec'      1 000 000 Bytes/sec
            - 'GBytes/sec'  1 000 000 000 Bytes/sec
            If transfer is 'simultaneous_ul_dl' then '7MBytes/sec' means "same 7MBytes/sec in both directions".
            You can also specify different values this way: 'ul:10MBytes/sec,dl:80Mbits/sec'
        :param bearer: bearer-name
            "UeAutomatic" is reserved name - it means that UE decides which bearer it will use (depends on load).
            Caution: if you don't provide this parameter then call will use same created once during method compilation.
        :param protocol: 'udp' or 'tcp'
        :return: None
        """
        errors = []
        self.direction = self._validate_and_return_direction(direction, errors)
        self.duration = self._validate_and_return_duration(duration, errors)
        self.throughput, self.ul_throughput, self.dl_throughput = self._validate_and_return_throughput(throughput, self.direction or '', errors)
        self.bearer = self._validate_and_return_bearer(bearer, errors)
        self.protocol = self._validate_and_return_protocol(protocol, errors)
        self.protocol_details = protocol_details if protocol_details else kwargs  # protocol_details will be validate by specific protocol impl
        if errors:
            raise ValueError("List of errors:\n  -{}".format('\n -'.join(errors)))
        logger.debug(str(self))

    def is_forever_duration(self):
        """
        Is forever time duration.

        :return: True / False
        """
        # because, default duration is 'forever duration'
        return self.has_default_duration()

    def has_default_duration(self):
        """
        Return True if duration is a default value otherwise False.

        :return: True / False
        """
        return True if self.DEFAULT_DURATION == self.duration else False

    def has_default_tput(self):
        """
        Return True if throughput is a default value otherwise False.

        :return: True / False
        """
        return True if self.DEFAULT_TPUT == self.throughput else False

    def has_default_bearer(self):
        """
        Return True if bearer is a default value otherwise False.

        :return: True / False
        """
        return True if self.DEFAULT_BEARER == self.bearer else False

    def has_default_protocol(self):
        """
        Return True if protocol is a default value otherwise False.

        :return: True / False
        """
        return True if self.DEFAULT_PROTOCOL == self.protocol else False

    @staticmethod
    def extract_throughput_string(throughput, direction):
        """
        Extract throughput requested per given direction

        Traffic may be either single direction or bi-directional.
        If expected throughput is given as '10Mbits/sec'
        it means such value for single direction traffic
        or it means same expected value for bi-directional traffic.
        But for bi-directional traffic throughput may have form
        'ul:10Mbits/sec,dl:80Mbits/sec' which sets different expectations for
        different directions.

        :param throughput: string (ul/dl values may differ)
        :param direction: 'ul' or 'dl'
        :return: throughput string per given direction
        """
        if not throughput:
            return throughput
        if ('ul:' in throughput) and ('dl:' in throughput) and (',' in throughput):
            # ul:10MBytes/sec,dl:80Mbits/sec
            # dl:10MBytes/sec,ul:80Mbits/sec
            if throughput.startswith('ul:'):
                ul_tput_str, dl_tput_str = throughput.split(',', 1)
            else:
                dl_tput_str, ul_tput_str = throughput.split(',', 1)
            if (not ul_tput_str.startswith('ul:')) or (not dl_tput_str.startswith('dl:')):
                example_tput = 'ul:10Mbits/sec,dl:80Mbits/sec'
                raise ValueError(f"Invalid throughput string: '{throughput}' - should be like '{example_tput}'")
            ul_tput_str = ul_tput_str[3:]
            dl_tput_str = dl_tput_str[3:]
            return ul_tput_str if direction == 'ul' else dl_tput_str
        else:
            return throughput

    def _validate_and_return_bearer(self, bearer, errors):
        # TODO Add validation
        return bearer

    def _validate_and_return_throughput(self, throughput, direction, errors):
        same_throughput, ul_throughput, dl_throughput = None, None, None
        try:
            if direction == 'simultaneous_ul_dl':
                ul_tput_str = self.extract_throughput_string(throughput, 'ul')
                dl_tput_str = self.extract_throughput_string(throughput, 'dl')
                _, ul_throughput, _ = self._validate_and_return_throughput(ul_tput_str, 'ul', errors)
                _, _, dl_throughput = self._validate_and_return_throughput(dl_tput_str, 'dl', errors)
            else:
                same_throughput = param_checker.tput_user_value2normalized(throughput, direction=direction)
                ul_throughput, dl_throughput = same_throughput, same_throughput
        except ValueError as exp:
            errors.append(str(exp))
            same_throughput, ul_throughput, dl_throughput = None, None, None
        return same_throughput, ul_throughput, dl_throughput

    def _validate_and_return_direction(self, direction, errors):
        """Allowed directions: ul, dl, simultaneous_ul_dl"""
        if isinstance(direction, six.string_types) and direction.lower() in ['ul', 'dl', 'simultaneous_ul_dl']:
            return direction.lower()
        else:
            errors.append(f"Invalid direction: '{direction}'\n{self._validate_and_return_direction.__doc__}")

    def _validate_and_return_duration(self, duration, errors):
        try:
            converted_duration = param_checker.convert_timestring(duration)
            return converted_duration
        except ValueError as exp:
            errors.append(str(exp))

    def _validate_and_return_protocol(self, protocol, errors):
        """Allowed protocols: udp, tcp, icmp, http"""
        if isinstance(protocol, six.string_types) and protocol in ['udp', 'tcp', 'icmp', 'http', 'ftp']:
            return protocol.lower()
        else:
            errors.append(f"Invalid protocol: '{protocol}'\n{self._validate_and_return_protocol.__doc__}")

    def __str__(self):
        duration_str = f'duration: {self.duration} sec'
        if self.direction == 'simultaneous_ul_dl':
            throughput_str = f'throughput: DL {self.dl_throughput} Kbits/sec & UL {self.ul_throughput} Kbits/sec'
        else:
            throughput_str = f'throughput: {self.direction.upper()} {self.throughput} Kbits/sec'
        bearer_str = f'bearer: {self.bearer}'
        protocol_str = f'protocol: {self.protocol}'
        protocol_details_str = f'protocol_details: {self.protocol_details}'
        info = f"{protocol_str}, {duration_str}, {throughput_str}, {bearer_str}, {protocol_details_str}"
        return f'{self.__class__.__name__}({info})'

    def __repr__(self):
        return f'{self.__class__.__name__}({str(vars(self))})'

    def __eq__(self, other):
        return vars(self) == vars(other)
